const fs = require('fs');
const vm = require('vm');
const assert = require('assert');
const source = fs.readFileSync('src/editors/PersonnelEditor.vue', 'utf8');
const json = JSON.parse(fs.readFileSync('src/config/personnel-form.json', 'utf8'));
const script = source.match(/<script>([\\s\\S]*?)<\\/script>/)[1]
  .replace(/"'^import .*;$/gm, '"'')
  .replace('export default', 'module.exports =');
const sandbox = { module: { exports: {} }, personnelConfig: json, SchemaForm: {} };
vm.runInNewContext(script, sandbox);
const component = sandbox.module.exports;
const state = component.data();
const writes = [];
