assert.equal(editor.option.layout, 'compact');
assert.equal(writes.length, 1);
assert.equal(writes[0].parentId, 1);
assert.equal(editor.pendingConfig, null);
editor.rule.find(item => item.field === 'unitLookup').on.search();
assert.equal(editor.pickerVisible, true);
editor.getPageConfig();
assert.equal(writes.length, 2);
console.log('Personnel local config readiness and behavior checks passed');
